const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:5000";

export interface Identity {
  id: string;
  identityId: string;
  detectionCount: number;
  firstSeen: string;
  lastSeen: string;
  confidence: string;
  consistency: number;
}

export interface IdentityTimeline {
  id: string;
  identityId: string;
  cameraId: string;
  timestamp: string;
  imagePath: string;
}

interface ApiResponse<T> {
  success: boolean;
  data: T;
  count?: number;
}

export async function getIdentities(): Promise<Identity[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/identities`, {
      cache: "no-store",
      credentials: "include",
    });

    const data: ApiResponse<Identity[]> = await response.json();
    return data.success ? data.data : [];
  } catch (error) {
    console.error("Failed to fetch identities:", error);
    return [];
  }
}

export async function getRecentIdentities(): Promise<Identity[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/identities/recent`, {
      cache: "no-store",
      credentials: "include",
    });

    const data: ApiResponse<Identity[]> = await response.json();
    return data.success ? data.data : [];
  } catch (error) {
    console.error("Failed to fetch recent identities:", error);
    return [];
  }
}

export async function getIdentity(
  identityId: string,
): Promise<Identity | null> {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/identities/${identityId}`,
      {
        cache: "no-store",
        credentials: "include",
      },
    );

    const data: ApiResponse<Identity> = await response.json();
    return data.success ? data.data : null;
  } catch (error) {
    console.error(`Failed to fetch identity ${identityId}:`, error);
    return null;
  }
}

export async function getIdentityTimeline(
  identityId: string,
): Promise<IdentityTimeline[]> {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/identities/${identityId}/observations`,
      {
        cache: "no-store",
        credentials: "include",
      },
    );

    const data: ApiResponse<IdentityTimeline[]> = await response.json();
    return data.success ? data.data : [];
  } catch (error) {
    console.error(
      `Failed to fetch timeline for identity ${identityId}:`,
      error,
    );
    return [];
  }
}
