"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";

import { getIdentity, getIdentityTimeline } from "@/lib/api/identities";

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

import { IdentityTimeline } from "@/components/identity-timeline";

import { ChevronLeft } from "lucide-react";

/* ================= TYPES MATCH BACKEND ================= */

interface Identity {
  id: string;
  identityId: string;
  confidence: string;
  consistency: number;
  detectionCount: number;
  firstSeen: string;
  lastSeen: string;
}

interface TimelineEvent {
  id: string;
  identityId: string;
  cameraId: string;
  timestamp: string;
  imagePath: string;
}

/* ======================================================= */

export default function IdentityDetailsPage() {
  const params = useParams();
  const router = useRouter();

  const identityId = params.identityId as string;

  const [identity, setIdentity] = useState<Identity | null>(null);
  const [timeline, setTimeline] = useState<TimelineEvent[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  /* ================= FETCH DATA ================= */

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);

      try {
        const [identityData, timelineData] = await Promise.all([
          getIdentity(identityId),
          getIdentityTimeline(identityId),
        ]);

        setIdentity(identityData);
        setTimeline(timelineData);
      } catch (error) {
        console.error("Error fetching identity details:", error);
      } finally {
        setIsLoading(false);
      }
    };

    if (identityId) fetchData();
  }, [identityId]);

  /* ================= HELPERS ================= */

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleString();
  };

  const getConfidenceBadge = (confidence: string) => {
    const value = parseFloat(confidence);

    if (value >= 0.9) return "bg-green-500/20 text-green-400";
    if (value >= 0.7) return "bg-yellow-500/20 text-yellow-400";

    return "bg-red-500/20 text-red-400";
  };

  /* ================= LOADING ================= */

  if (isLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-10 w-40 bg-[#333]" />

        <div className="grid grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <Skeleton key={i} className="h-24 bg-[#333]" />
          ))}
        </div>

        <Skeleton className="h-96 bg-[#333]" />
      </div>
    );
  }

  /* ================= NOT FOUND ================= */

  if (!identity) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-400">Identity not found</p>

        <button
          onClick={() => router.back()}
          className="mt-4 px-4 py-2 bg-cyan-500/20 text-cyan-400 rounded hover:bg-cyan-500/30"
        >
          Go Back
        </button>
      </div>
    );
  }

  /* ================= UI ================= */

  return (
    <div className="space-y-6 p-6">
      {/* ================= HEADER ================= */}

      <div className="flex items-center gap-4">
        <button
          onClick={() => router.back()}
          className="p-2 hover:bg-[#333] rounded transition-colors"
        >
          <ChevronLeft size={24} className="text-gray-400" />
        </button>

        <div>
          <h1 className="text-3xl font-bold text-white">
            Identity Investigation
          </h1>

          <p className="text-gray-400 font-mono mt-1">{identity.identityId}</p>
        </div>
      </div>

      {/* ================= SUMMARY ================= */}

      <Card className="bg-[#222] border-[#333] p-6">
        <div className="grid grid-cols-4 gap-6">
          <div>
            <p className="text-sm text-gray-500 mb-2">Identity ID</p>
            <p className="text-lg font-mono text-cyan-400">
              {identity.identityId}
            </p>
          </div>

          <div>
            <p className="text-sm text-gray-500 mb-2">Detection Count</p>
            <p className="text-lg font-bold text-white">
              {identity.detectionCount}
            </p>
          </div>

          <div>
            <p className="text-sm text-gray-500 mb-2">First Seen</p>
            <p className="text-sm text-gray-300">
              {formatDate(identity.firstSeen)}
            </p>
          </div>

          <div>
            <p className="text-sm text-gray-500 mb-2">Last Seen</p>
            <p className="text-sm text-gray-300">
              {formatDate(identity.lastSeen)}
            </p>
          </div>
        </div>

        {/* confidence + consistency */}

        <div className="grid grid-cols-2 gap-6 mt-6 pt-6 border-t border-[#333]">
          <div>
            <p className="text-sm text-gray-500 mb-2">Confidence Score</p>

            <Badge
              className={`${getConfidenceBadge(identity.confidence)} border-0`}
            >
              {(parseFloat(identity.confidence) * 100).toFixed(1)}%
            </Badge>
          </div>

          <div>
            <p className="text-sm text-gray-500 mb-2">Consistency Score</p>

            <Badge className="bg-blue-500/20 text-blue-400 border-0">
              {(identity.consistency * 100).toFixed(1)}%
            </Badge>
          </div>
        </div>
      </Card>

      {/* ================= TIMELINE ================= */}

      <div>
        <h2 className="text-xl font-bold text-white mb-4">
          Detection Timeline
        </h2>

        <IdentityTimeline events={timeline} isLoading={isLoading} />
      </div>
    </div>
  );
}
